with feeders as (
    select
        md5(upper('HUB_FINANCIAL_TRANSACTION|' || (HUB_FINANCIAL_TRANSACTION_BK__PTRANSACTION_ID))) as HUB_FINANCIAL_TRANSACTION_HK
        , cast(null as varchar) as SERVICE_TAX_EXEMPTION_INDICATOR
        , SERVICE_TAX_AMT as SERVICE_TAX_AMOUNT
        , cast(null as varchar) as CESS_AMOUNT
        , STATE_GST as SGST_AMOUNT
        , cast(null as varchar) as COMPONENT_TAX_AMOUNT
        , CENTRAL_GST as CGST_AMOUNT
        , I_GST as IGST_AMOUNT
        , cast(null as varchar) as TDS_RATE
        , cast(null as varchar) as SERVICE_TAX_RATE
        , cast(null as varchar) as SERVICE_TAX_REGISTRATION_NUMBER
        , 'BJAZ_HEALTH_WEBSERVICE_INFO' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_health_webservice_info') }}
    where (nullif(trim(PTRANSACTION_ID),'')) is not null
    union all
    select
        md5(upper('HUB_FINANCIAL_TRANSACTION|' || (HUB_FINANCIAL_TRANSACTION_BK__UTR_NO))) as HUB_FINANCIAL_TRANSACTION_HK
        , cast(null as varchar) as SERVICE_TAX_EXEMPTION_INDICATOR
        , SERVICE_TAX as SERVICE_TAX_AMOUNT
        , cast(null as varchar) as CESS_AMOUNT
        , cast(null as varchar) as SGST_AMOUNT
        , cast(null as varchar) as COMPONENT_TAX_AMOUNT
        , cast(null as varchar) as CGST_AMOUNT
        , cast(null as varchar) as IGST_AMOUNT
        , TDS_RATE as TDS_RATE
        , SERVICE_TAX_RATE as SERVICE_TAX_RATE
        , cast(null as varchar) as SERVICE_TAX_REGISTRATION_NUMBER
        , 'BJAZ_HM_HCM_EXTRACT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcm_extract') }}
    where (nullif(trim(UTR_NO),'')) is not null
    union all
    select
        md5(upper('HUB_FINANCIAL_TRANSACTION|' || (HUB_FINANCIAL_TRANSACTION_BK__TPA_TRANS_KEY))) as HUB_FINANCIAL_TRANSACTION_HK
        , cast(null as varchar) as SERVICE_TAX_EXEMPTION_INDICATOR
        , SERVICE_TAX_AMOUNT as SERVICE_TAX_AMOUNT
        , cast(null as varchar) as CESS_AMOUNT
        , cast(null as varchar) as SGST_AMOUNT
        , cast(null as varchar) as COMPONENT_TAX_AMOUNT
        , cast(null as varchar) as CGST_AMOUNT
        , cast(null as varchar) as IGST_AMOUNT
        , cast(null as varchar) as TDS_RATE
        , cast(null as varchar) as SERVICE_TAX_RATE
        , SERVICE_TAX_NO as SERVICE_TAX_REGISTRATION_NUMBER
        , 'BJAZ_TPA_CLAIM_DETAILS_WS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_tpa_claim_details_ws') }}
    where (nullif(trim(TPA_TRANS_KEY),'')) is not null
),

resolved as (
    select
        HUB_FINANCIAL_TRANSACTION_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SERVICE_TAX_EXEMPTION_INDICATOR end) as SERVICE_TAX_EXEMPTION_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SERVICE_TAX_AMOUNT end) as SERVICE_TAX_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CESS_AMOUNT end) as CESS_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SGST_AMOUNT end) as SGST_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COMPONENT_TAX_AMOUNT end) as COMPONENT_TAX_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CGST_AMOUNT end) as CGST_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then IGST_AMOUNT end) as IGST_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TDS_RATE end) as TDS_RATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SERVICE_TAX_RATE end) as SERVICE_TAX_RATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SERVICE_TAX_REGISTRATION_NUMBER end) as SERVICE_TAX_REGISTRATION_NUMBER,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_FINANCIAL_TRANSACTION_HK
),

hashed as (
    select
        *,
        case when SERVICE_TAX_EXEMPTION_INDICATOR is not null or SERVICE_TAX_AMOUNT is not null or CESS_AMOUNT is not null or SGST_AMOUNT is not null or COMPONENT_TAX_AMOUNT is not null or CGST_AMOUNT is not null or IGST_AMOUNT is not null or TDS_RATE is not null or SERVICE_TAX_RATE is not null or SERVICE_TAX_REGISTRATION_NUMBER is not null
                     then md5(upper(coalesce(cast(SERVICE_TAX_EXEMPTION_INDICATOR as varchar), '') || '|' || coalesce(cast(SERVICE_TAX_AMOUNT as varchar), '') || '|' || coalesce(cast(CESS_AMOUNT as varchar), '') || '|' || coalesce(cast(SGST_AMOUNT as varchar), '') || '|' || coalesce(cast(COMPONENT_TAX_AMOUNT as varchar), '') || '|' || coalesce(cast(CGST_AMOUNT as varchar), '') || '|' || coalesce(cast(IGST_AMOUNT as varchar), '') || '|' || coalesce(cast(TDS_RATE as varchar), '') || '|' || coalesce(cast(SERVICE_TAX_RATE as varchar), '') || '|' || coalesce(cast(SERVICE_TAX_REGISTRATION_NUMBER as varchar), '')))
                end as SAT_FINTXN_TAX_HASHDIFF
    from resolved
)

select * from hashed
where HUB_FINANCIAL_TRANSACTION_HK is not null
  and SAT_FINTXN_TAX_HASHDIFF is not null
